param([Parameter(Mandatory=$true)][ValidatePattern('^[A-Za-z0-9_-]+$')][string]$CellId,[Parameter(Mandatory=$true)][string]$Destination)
$ErrorActionPreference='Stop'; $run='C:\Users\BotTest\274bot-runs\managed-tile-cpu-'+$CellId; if(-not(Test-Path $run)){throw 'Run missing'}; $dest=Join-Path $Destination $CellId; New-Item -ItemType Directory -Path $dest|Out-Null; Copy-Item (Join-Path $run '*') $dest -Recurse -Force; $raw=@(Get-ChildItem $run -Recurse -File -Filter receipt.json|ForEach-Object{try{(Get-Content $_.FullName -Raw|ConvertFrom-Json).run_dir}catch{}}); foreach($r in $raw){if(Test-Path $r){Copy-Item $r (Join-Path $dest ('raw-run-'+[guid]::NewGuid().ToString())) -Recurse -Force}}; [ordered]@{schema='tile-cpu-archive-v1';cell_id=$CellId;raw_receipt_dirs=$raw;functional_only=$true;performanceAcceptance=$false}|ConvertTo-Json -Depth 6|Set-Content (Join-Path $dest 'archive-manifest.json')
